    # rectangle bbox of o
    ps=g==o; ys,xs=np.where(ps)
    r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
    # interior: bg cells inside rect not reachable from outside
    vis=np.zeros_like(g,bool); out=[]
    st=[(i,j) for i in range(H) for j in range(W) if g[i,j]==bg]
    for s0,s1 in [(0,0),(0,W-1),(H-1,0),(H-1,W-1)]: pass
    frontier=[]
    for i in range(H):
        for j in (0,W-1):
            if g[i,j]==bg: frontier.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i,j]==bg: frontier.append((i,j))
    seen=set(frontier)
    for (i,j) in frontier:
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and g[ni,nj]==bg and (ni,nj) not in seen:
                seen.add((ni,nj)); frontier.append((ni,nj))
