    ring=set(ring)
    gap=[(i,j) for (i,j) in ring if g[i,j]==bg]
    def emit(i,j,di,dj):
        while True:
            i+=di;j+=dj
            if not(0<=i<H and 0<=j<W): break
            result[i,j]=4
    for (gi,gj) in gap:
        if c0==gj: # left wall -> away = left: up-left, down-left
            emit(gi,gj,-1,-1); emit(gi,gj,1,-1)
            emit(gi,c0-gj-1,-1,0); emit(gi,c0-gj-1,1,0)
