def floodfill(g,objvals):
    g=np.array(g); H,W=g.shape
    seen=set(); q=deque()
    edges={(i,j) for i in range(H) for j in range(W) if i in(0,H-1) or j in(0,W-1)}
    touch=set(i for i,j in edges if g[i][j] not in objvals) | set(j for i,j in edges if g[i][j] not in objvals)
    # start flood from border cells whose value != any objval
    cells=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] not in objvals:
                if i in(0,H-1) or j in(0,W-1): cells.append((i,j))
    while cells:
        c=cells.pop()
        if c in seen: continue
        seen.add(c)
        x,y=c
        for dx in(-1,0,1):
            for dy in(-1,0,1):
                p=(x+dx,y+dy)
                if 0<=p[0]<H and 0<=p[1]<W and g[p]!=5 and p not in seen: cells.append(p)
    pred={(i,j) for i in range(H) for j in range(W) if g[i][j]!=5 and (i,j) not in seen}
    return pred
