def comps(g,color):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=color and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]!=color and (nx,ny) not in seen:
                            st.append((nx,ny))
                out.append(comp)
    return out
